<script setup>
import {computed,onMounted,reactive,ref} from 'vue';
const props=defineProps({mode:String,indexUrl:String,createUrl:String,storeUrl:String,updateUrl:String,csrf:String,payload:String,errors:String,old:String});
function decode(v,fallback={}){try{return typeof v==='string'?JSON.parse(v||'{}'):v||fallback}catch{return fallback}}
const initial=decode(props.payload),errorData=decode(props.errors),oldData=decode(props.old);
const state=reactive({rows:[],pagination:{},stats:{},loading:false,error:'',search:'',form:{name:oldData.name??initial.role?.name??'',display_name:oldData.display_name??initial.role?.display_name??'',description:oldData.description??initial.role?.description??'',permissions:(oldData.permissions??initial.selected_permissions??[]).map(Number)}});
const permissionGroups=computed(()=>initial.permission_groups||{}),rolePermissionGroups=computed(()=>{const groups={};for(const item of initial.permissions||[])(groups[item.group_name||'Permissions']??=[]).push(item);return groups}),role=computed(()=>initial.role||{}),users=computed(()=>initial.users||[]);
async function load(url=props.indexUrl){state.loading=true;state.error='';try{const response=await fetch(url,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},credentials:'same-origin'});const data=await response.json();if(!response.ok)throw new Error(data.message||'Unable to load roles');state.rows=data.roles||[];state.pagination=data.pagination||{};state.stats=data.stats||{}}catch(e){state.error=e.message}finally{state.loading=false}}
function page(link){if(link.url)load(link.url)}
function toggle(id,event){const n=Number(id);if(event.target.checked&&!state.form.permissions.includes(n))state.form.permissions.push(n);if(!event.target.checked)state.form.permissions=state.form.permissions.filter(x=>x!==n)}
function checked(id){return state.form.permissions.includes(Number(id))}
function submit(event){const form=event.currentTarget;if(!form.reportValidity())event.preventDefault()}
function destroy(url,name){if(confirm('Delete role '+name+'?')){const form=document.createElement('form');form.method='POST';form.action=url;form.innerHTML='<input name="_token" value="'+props.csrf+'"><input name="_method" value="DELETE">';document.body.append(form);form.submit()}}
onMounted(()=>{if(props.mode==='index')load()});
</script>
<template>
<div class="dashboard-section roles-page">
<template v-if="mode==='index'">
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1>Roles and Permissions</h1><p>Manage access roles and their permissions.</p></div><a :href="createUrl" class="btn btn-primary"><i class="bi bi-plus-lg"></i> Create Role</a></div>
<div class="row g-3 mb-4"><div class="col-md-3" v-for="(value,key) in state.stats" :key="key"><div class="dashboard-panel p-3"><span class="text-muted text-capitalize">{{key}}</span><strong class="d-block fs-4">{{value}}</strong></div></div></div>
<div v-if="state.error" class="alert alert-danger">{{state.error}} <button class="btn btn-sm btn-light" @click="load()">Retry</button></div>
<div class="dashboard-panel p-3 table-responsive"><table class="table align-middle"><thead><tr><th>Role</th><th>Description</th><th>Users</th><th>Permissions</th><th>Type</th><th class="text-end">Actions</th></tr></thead><tbody><tr v-if="state.loading"><td colspan="6" class="text-center py-4">Loading…</td></tr><tr v-for="r in state.rows" :key="r.id"><td><strong>{{r.display_name}}</strong><small class="d-block text-muted">{{r.name}}</small></td><td>{{r.description||'—'}}</td><td>{{r.users_count}}</td><td>{{r.permissions_count}}</td><td><span class="badge" :class="r.is_system?'bg-secondary':'bg-primary'">{{r.is_system?'System':'Custom'}}</span></td><td class="text-end"><a :href="r.show_url" class="btn btn-sm btn-light"><i class="bi bi-eye"></i></a><a :href="r.edit_url" class="btn btn-sm btn-warning ms-1"><i class="bi bi-pencil"></i></a><button v-if="!r.is_system" class="btn btn-sm btn-danger ms-1" @click="destroy(r.delete_url,r.display_name)"><i class="bi bi-trash"></i></button></td></tr><tr v-if="!state.loading&&!state.rows.length"><td colspan="6" class="text-center">No roles found.</td></tr></tbody></table><nav v-if="state.pagination.links?.length" class="d-flex gap-1"><button v-for="(l,i) in state.pagination.links" :key="i" class="btn btn-sm" :class="l.active?'btn-primary':'btn-light'" :disabled="!l.url" @click="page(l)" v-html="l.label"></button></nav></div>
</template>
<template v-else-if="mode==='create'||mode==='edit'">
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1>{{mode==='create'?'Create Role':'Edit Role'}}</h1><p>Configure the role and access permissions.</p></div><a :href="indexUrl" class="btn btn-light"><i class="bi bi-arrow-left"></i> Back to Roles</a></div>
<form :action="mode==='create'?storeUrl:updateUrl" method="POST" class="dashboard-panel p-4" @submit="submit"><input type="hidden" name="_token" :value="csrf"><input v-if="mode==='edit'" type="hidden" name="_method" value="PUT">
<div v-if="Object.keys(errorData).length" class="alert alert-danger"><strong>Please correct the following errors:</strong><ul class="mb-0"><li v-for="(messages,key) in errorData" :key="key">{{messages[0]}}</li></ul></div>
<div class="mb-3" v-if="mode==='create'"><label class="form-label" for="name">Role identifier</label><input id="name" name="name" class="form-control" maxlength="80" required v-model="state.form.name"><div v-if="errorData.name" class="text-danger small">{{errorData.name[0]}}</div></div>
<div class="mb-3"><label class="form-label" for="display_name">Display name</label><input id="display_name" name="display_name" class="form-control" maxlength="120" required v-model="state.form.display_name"><div v-if="errorData.display_name" class="text-danger small">{{errorData.display_name[0]}}</div></div>
<div class="mb-4"><label class="form-label" for="description">Description</label><textarea id="description" name="description" class="form-control" rows="3" maxlength="500" v-model="state.form.description"></textarea></div>
<section><h5>Permissions</h5><div v-for="(permissions,group) in permissionGroups" :key="group" class="border rounded p-3 mb-3"><h6 class="text-capitalize">{{group}}</h6><div class="row g-2"><label v-for="permission in permissions" :key="permission.id" class="col-md-6 d-flex gap-2 align-items-center"><input type="checkbox" :checked="checked(permission.id)" @change="toggle(permission.id,$event)"><span>{{permission.display_name}}</span></label></div></div><input v-for="id in state.form.permissions" :key="id" type="hidden" name="permissions[]" :value="id"></section>
<div class="d-flex justify-content-end gap-2 mt-4"><a :href="indexUrl" class="btn btn-light">Cancel</a><button class="btn btn-primary" type="submit">{{mode==='create'?'Create Role':'Save Changes'}}</button></div></form>
</template>
<template v-else>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1>{{role.display_name}}</h1><p>{{role.description||role.name}}</p></div><div><a :href="role.edit_url" class="btn btn-warning"><i class="bi bi-pencil"></i> Edit</a><a :href="indexUrl" class="btn btn-light ms-2">Back</a></div></div>
<div class="row g-4"><div class="col-lg-8"><section class="dashboard-panel p-4 mb-4"><h5>Permissions</h5><div v-for="(items,group) in rolePermissionGroups" :key="group" class="mb-3"><h6>{{group}}</h6><span v-for="permission in items.filter(p=>initial.permissions?.some(x=>x.id===p.id))" :key="permission.id" class="badge bg-light text-dark border me-2 mb-2">{{permission.display_name}}</span></div><p v-if="!initial.permissions?.length" class="text-muted">No permissions assigned.</p></section></div><div class="col-lg-4"><section class="dashboard-panel p-4"><h5>Assigned users ({{users.length}})</h5><div v-for="user in users" :key="user.id" class="py-2 border-bottom">{{user.name}}<small class="d-block text-muted">{{user.email}}</small></div><p v-if="!users.length" class="text-muted">No users assigned.</p></section></div></div>
</template></div>
</template>
